(() => {const nav = document.querySelector(".nav");const menuBtn = document.querySelector(".menu-toggle");if (!nav || !menuBtn) return;const closeMenu = () => {nav.classList.remove("is-open");menuBtn.setAttribute("aria-expanded","false")};menuBtn.addEventListener("click",() => {const isOpen = nav.classList.toggle("is-open");menuBtn.setAttribute("aria-expanded",String(isOpen))});nav.querySelectorAll("nav a").forEach((link) => {link.addEventListener("click",closeMenu)});const mql = window.matchMedia("(max-width: 900px)");const handleResize = () => {if (!mql.matches) closeMenu()};if (mql.addEventListener) {mql.addEventListener("change",handleResize)} else {mql.addListener(handleResize)}})();(() => {const toggle = document.querySelector(".lang-toggle");if (!toggle) return;const krLabel = toggle.querySelector(".lang-kr");const enLabel = toggle.querySelector(".lang-en");const apply = (lang) => {document.documentElement.lang = lang;if (krLabel) krLabel.classList.toggle("is-active",lang === "ko");if (enLabel) enLabel.classList.toggle("is-active",lang === "en")};toggle.addEventListener("click",() => {const next = document.documentElement.lang === "en" ? "ko": "en";apply(next)});apply(document.documentElement.lang === "en" ? "en": "ko")})();(() => {const iframe = document.querySelector(".sponsor-hero-video");if (!(iframe instanceof HTMLIFrameElement)) return;const postPlayerCommand = (func,args = []) => {if (!iframe.contentWindow) return;iframe.contentWindow.postMessage(JSON.stringify({event: "command",func,args}),"*")};const applyHighQuality = () => {["hd1080","hd720","large"].forEach((quality) => {postPlayerCommand("setPlaybackQualityRange",[quality]);postPlayerCommand("setPlaybackQuality",[quality])})};const initHeroVideo = () => {postPlayerCommand("mute");applyHighQuality();postPlayerCommand("playVideo");window.setTimeout(applyHighQuality,600);window.setTimeout(applyHighQuality,1400)};iframe.addEventListener("load",initHeroVideo);window.setTimeout(initHeroVideo,320)})();
